path = "app/assets/stylesheets/card-columns.css"
s = File.read(path)
old = <<-CSS
    .card__boosts,
    .card__comments {
      --column-gap: 0.8ch;

      display: flex;
      margin-block-end: calc(var(--block-space) * -1.7);
      margin-inline-end: calc(var(--card-padding-inline) * -0.5);

      .icon {
        --icon-size: 1.6em;

        color: var(--card-color);
      }
    }
CSS
new = old + <<-CSS

    .card__boosts {
      margin-inline-end: 0;

      img {
        block-size: 1.3em;
        inline-size: 1.3em;
      }
    }
CSS
raise "not found" unless s.include?(old)
s = s.sub(old, new)

# Hide boosts along with comments when a background image is set (revealed on hover)
s = s.gsub("      .card__meta,\n      .card__comments,\n", "      .card__meta,\n      .card__boosts,\n      .card__comments,\n")
s = s.gsub("          .card__footer,\n          .card__comments,\n", "          .card__footer,\n          .card__boosts,\n          .card__comments,\n")
File.write(path, s)

path = "app/assets/stylesheets/trays.css"
s = File.read(path)
s = s.sub("    .card__steps,\n    .card__comments,\n", "    .card__steps,\n    .card__boosts,\n    .card__comments,\n")
File.write(path, s)
EOF
